@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_593012d5c60f460ebe5fa8f712cd9515.Models
@using sv_593012d5c60f460ebe5fa8f712cd9515.Services
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav>
    <a href="/recipes/1?sort=@Sort">Italian</a> |
    <a href="/recipes/2?sort=@Sort">Chinese</a> |
    <a href="/recipes/3?sort=@Sort">Mexican</a>
</nav>

<div style="margin-top: 1rem;">
    <label>
        Sort:
        <select @bind="SelectedSort" @bind:after="OnSortChanged">
            <option value="newest">Newest</option>
            <option value="popular">Popular</option>
        </select>
    </label>
</div>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert" style="margin-top: 1rem;">
        <p>@_error</p>
        <button class="btn btn-outline-danger" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <div style="margin-top: 1rem;">
        <p><em>Loading recipes…</em></p>
    </div>
}
else
{
    @if (_isRefreshing)
    {
        <div style="margin-top: 0.5rem;">
            <small><em>Refreshing…</em></small>
        </div>
    }

    <ul style="margin-top: 1rem;">
        @foreach (var recipe in GetSortedRecipes())
        {
            <li>
                <strong>@recipe.Title</strong> — @recipe.Description
                <br />
                <small>Prep time: @recipe.PrepTimeMinutes min</small>
            </li>
        }
    </ul>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private string SelectedSort { get; set; } = "newest";

    private List<Recipe>? _recipes;
    private string? _error;
    private bool _isRefreshing;
    private int _loadedCuisineId;

    private CancellationTokenSource? _loadCts;

    protected override void OnParametersSet()
    {
        SelectedSort = string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            ? "popular"
            : "newest";

        // Only reload data when cuisine changes
        if (CuisineId != _loadedCuisineId)
        {
            _ = LoadRecipesAsync();
        }
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = new CancellationTokenSource();
        var cts = _loadCts;

        _error = null;
        _isRefreshing = _recipes is not null;
        var cuisineId = CuisineId;

        StateHasChanged();

        try
        {
            var results = await RecipeService.GetByCuisineAsync(cuisineId, cts.Token);

            if (cts.Token.IsCancellationRequested)
                return;

            _recipes = results;
            _loadedCuisineId = cuisineId;
            _isRefreshing = false;
            _error = null;
        }
        catch (OperationCanceledException)
        {
            // Load was superseded by a newer request — do nothing
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _isRefreshing = false;
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _isRefreshing = false;
            _error = "Something went wrong while loading recipes. Please try again.";
        }

        StateHasChanged();
    }

    private void OnSortChanged()
    {
        Sort = SelectedSort;
        Navigation.NavigateTo($"/recipes/{CuisineId}?sort={SelectedSort}", replace: true);
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null)
            return new List<Recipe>();

        return string.Equals(SelectedSort, "popular", StringComparison.OrdinalIgnoreCase)
            ? _recipes.OrderByDescending(r => r.PrepTimeMinutes).ToList()
            : _recipes.OrderByDescending(r => r.Id).ToList();
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    public void Dispose()
    {
        _loadCts?.Cancel();
        _loadCts?.Dispose();
    }
}

