namespace sv_8d797fe30f484227bf1928a48353c68e.Services;

public record Recipe(int Id, string Title, string Description, int PrepTimeMinutes);

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> _data = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Spaghetti Carbonara", "Classic Roman pasta with eggs, pecorino, guanciale, and black pepper.", 25),
            new(2, "Margherita Pizza", "Neapolitan pizza with San Marzano tomatoes, mozzarella, and fresh basil.", 45),
            new(3, "Risotto alla Milanese", "Creamy saffron-infused risotto from Milan.", 35),
            new(4, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream.", 30),
        },
        [2] = new List<Recipe>
        {
            new(5, "Chicken Tikka Masala", "Grilled chicken in a creamy spiced tomato sauce.", 40),
            new(6, "Palak Paneer", "Fresh spinach cooked with cubes of paneer cheese and aromatic spices.", 30),
            new(7, "Biryani", "Fragrant basmati rice layered with spiced meat and caramelized onions.", 60),
            new(8, "Samosa", "Crispy pastry filled with spiced potatoes and peas.", 50),
        },
        [3] = new List<Recipe>
        {
            new(9, "Sushi Rolls", "Vinegared rice with fresh fish and vegetables wrapped in nori.", 45),
            new(10, "Ramen", "Rich pork bone broth with wheat noodles, chashu, and soft-boiled egg.", 120),
            new(11, "Tempura", "Lightly battered and deep-fried seafood and vegetables.", 25),
            new(12, "Miso Soup", "Traditional soup with dashi broth, tofu, wakame, and white miso.", 15),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call
        await Task.Delay(2000, cancellationToken);

        if (_data.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_8d797fe30f484227bf1928a48353c68e.Services
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav>
    <a href="/recipes/1?sort=@_currentSort">Italian</a> |
    <a href="/recipes/2?sort=@_currentSort">Indian</a> |
    <a href="/recipes/3?sort=@_currentSort">Japanese</a>
</nav>

<div style="margin-top: 0.5rem;">
    Sort:
    <a href="/recipes/@CuisineId?sort=newest">Newest</a> |
    <a href="/recipes/@CuisineId?sort=popular">Popular</a>
</div>

<hr />

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes...</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <div class="recipe-list">
        @foreach (var recipe in GetSortedRecipes())
        {
            <div class="card mb-3">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <p class="card-text">@recipe.Description</p>
                    <small class="text-muted">Prep time: @recipe.PrepTimeMinutes minutes</small>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _error;
    private bool _isRefreshing;
    private string _currentSort = "newest";
    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        var sort = string.IsNullOrWhiteSpace(Sort) ? "newest" : Sort;
        _currentSort = sort;

        // Only reload data if the cuisine changed
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _error = null;

        if (_recipes is not null)
        {
            // Already have data on screen — show refreshing indicator
            _isRefreshing = true;
        }

        try
        {
            var results = await RecipeService.GetByCuisineAsync(CuisineId, token);

            // Check cancellation after await in case a newer request superseded this one
            token.ThrowIfCancellationRequested();

            _recipes = results;
            _loadedCuisineId = CuisineId;
            _isRefreshing = false;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Request was superseded by a newer one — do nothing
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _error = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null) return new();

        return _currentSort switch
        {
